def _extract_security_audits(html: str, identifier: str) -> Dict[str, str]:
    audits: Dict[str, str] = {}
    for audit in ('agent-trust-hub', 'socket', 'snyk'):
        idx = html.find(f'/security/{audit}')
        if idx == -1:
